#!/usr/bin/env bash
# Reuse the exact synthetic inputs generated by test-msys2.sh.
set -euo pipefail
source_root=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd)
install_dir=${FFMPEG_LIVE_INSTALL_DIR:-"$source_root/../install-linux-baseline"}
fixture_dir=${FFMPEG_LIVE_FIXTURE_DIR:-"$source_root/../results-msys2-baseline"}
result_dir=${FFMPEG_LIVE_RESULT_DIR:-"$source_root/../results-linux-baseline"}
export LD_LIBRARY_PATH="$install_dir/lib${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
mkdir -p -- "$result_dir"
"$install_dir/bin/ffmpeg" -hide_banner -version > "$result_dir/tested-version.txt"

for codec in h264 hevc; do
    for reorder in 0 3; do
        fixture="$fixture_dir/${codec}-b${reorder}.mp4"
        for threads in 2 12; do
            "$install_dir/bin/ffmpeg" -hide_banner -loglevel error -nostdin -y \
                -threads "$threads" -thread_type frame -i "$fixture" \
                -map 0:v:0 -an -c:v rawvideo -fps_mode passthrough \
                -f framehash "$result_dir/${codec}-b${reorder}-t${threads}.sha256"
        done
        cmp "$result_dir/${codec}-b${reorder}-t2.sha256" \
            "$result_dir/${codec}-b${reorder}-t12.sha256"
    done
    for threads in 2 4 8 12; do
        "$install_dir/bin/latency_probe" "$fixture_dir/${codec}-b0.mp4" \
            "$threads" 25 frame > "$result_dir/${codec}-t${threads}.csv"
    done
done

python3 "$source_root/tools/live-async/summarize_probe.py" "$result_dir"
python3 - "$fixture_dir" "$result_dir" <<'PY'
import pathlib
import sys
windows_dir, linux_dir = map(pathlib.Path, sys.argv[1:])
for codec in ("h264", "hevc"):
    for reorder in (0, 3):
        name = f"{codec}-b{reorder}-t2.sha256"
        def decoded_rows(path):
            return [line for line in path.read_text().splitlines()
                    if line and not line.startswith("#")]
        assert decoded_rows(windows_dir / name) == decoded_rows(linux_dir / name), name
print("PASS: Windows and Linux decoded hashes/PTS match for all four fixtures.")
PY
